/*! 
 * Theme: 阴雨天
 * Author: endlessrefrain
 * 当前版本: 1.0.0 | 最后更新: 2026-03-11
 */

/*! 本美化仅限个人自用，请勿私自二传/二改，参考/借鉴(即使只是部分)请告知我并注明出处 */

/*! 禁止用于任何商业化用途，贩子死全家 */

@import url("data:text/css,%40font-face%7Bfont-family%3A%22ZSFT-720%22%3Bsrc%3Aurl(%22https%3A%2F%2Ffontsapi.zeoseven.com%2F720%2Fmain.woff2%22)%20format(%22woff2%22)%3Bfont-style%3Anormal%3Bfont-weight%3A400%3Bfont-display%3Aswap%3B%7D");

@import url("https://fontsapi.zeoseven.com/301/main/result.css");

@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
  font-family: "KingHwaOldSong";
  font-weight: normal;
}

/*! ======= 变量设置 ======= */
:root{
  --头像大小: 60%;
  --头像比例: 4/3;
  --Char头像显示区域: 50%; /* 0%-100%， 从上往下 */
  --User头像显示区域: 30%;

  --气泡两侧边距: 0.8rem;
  --气泡上下间距: 1rem;
  --气泡模糊: 20px;
  --正文首行缩进: 2em;

  --頂部文案-1: '“我';
  /* 用\A換行符和空格控制排版 */
  --頂部文案-2: '们一起\A去死            \A一起忘记\A    曾经发生过的事情';

  --Char名: "Possessive";
  --User名: "Jealousy";
  --思维链文案: "［倘若我是你，而你是我］";
  --思维链展开: "你说的‘和我在一起感觉很窒息’，是什么意思？";

  --顶栏图标大小: calc(var(--mainFontSize) * 1.25);

  --装饰字: "GenWanMin2 TC R";
  --花体英文: "ZSFT-720";
  --shadow-1: rgba(255,255,255,0.1);
  --gap-1: 1rem;
  --ts-size: 0.7rem;
  --color-1: rgba(21,21,21,1);
}

/* 给不同角色设置不同的头像显示区域，修改引号内文字和百分比 */
#chat .mes[ch_name="祝昀"] .avatar img {
  object-position: center 20%;
}

#chat .mes[ch_name="琥珀糖"] .avatar img {
  object-position: center 20%;
}


/*! ======= 通用设置 ======= */
::-webkit-scrollbar {
  width: 4px;
}

::-webkit-scrollbar-thumb {
  border-radius: 1px !important;
  border: none !important;
  box-shadow: none !important;
}

.avatar img,
body.big-avatar .avatar img{
  border: none;
  box-shadow: none;
}

/*! ======= 聊天区域 ======= */
/* by nakari */
#form_sheld {
  margin: 0 auto !important;
}

#sheld {
  /* by nakari */
  body:not(.waifuMode) & {
    top: var(--bottomFormBlockSize);
    height: calc(100dvh - var(--bottomFormBlockSize));
    min-height: calc(100dvh - var(--bottomFormBlockSize));
  }
}

#chat {
  align-items: center;
  border: none;
  background: none;
  scrollbar-width: thin;
}

#bg1::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: url("https://files.catbox.moe/kp58v9.png") center/ contain repeat;
  mix-blend-mode: overlay;
  pointer-events: none;
}

/* 气泡 */
#chat .mes:not(.smallSysMes) {
  flex-direction: column;
  width: calc(100% - var(--气泡两侧边距));
  padding: 0.3rem;
  margin: var(--气泡上下间距) auto;
  background: var(--SmartThemeChatTintColor);
  backdrop-filter: blur(var(--气泡模糊)) !important;
  border-radius: 2px;
  box-shadow:
    0 0 2px var(--shadow-1),
    1px 1px 1px var(--shadow-1);
}

.last_mes {
  margin-bottom: 30px !important;
  .mesAvatarWrapper {
    padding-bottom: 0;
  }
}

.last_mes[is_user="false"]:not(.smallSysMes) {
  padding-bottom: 30px !important;
}

/* 文字区域 */
.mes_block {
  position: relative;
  overflow: visible;
  padding: 0;
}

.mes_text {
  padding: 1em 5px;
  text-align: justify;
  p:not(blockquote p) {
    text-indent: var(--正文首行缩进);
  }
  summary {
    text-align: center;
    list-style: none;
    color: var(--SmartThemeEmColor);
    margin-bottom: 1em;
    text-decoration: underline;
    text-decoration-style: dotted;
    text-underline-offset: 0.3em;
  }
  summary::-webkit-details-marker {
    display: none;
  }
}

.mes_text p:empty {
  display: none;
}

.mes_text p:last-child {
  margin-bottom: 0;
}

/* 头像部分 */
.mesAvatarWrapper {
  width: 100%;
  display: flex;
  align-items: flex-end;
  margin-bottom: calc(var(--gap-1) - var(--ts-size));
  position: relative;
  &::before {
    content: var(--頂部文案-1);
    font-family: "KingHwaOldSong";
    position: absolute;
    top: 30px;
    left: calc(50% + 0.65em);
    font-size: 1.75rem;
    color: var(--SmartThemeQuoteColor);
    z-index: 5;
  }
  &::after {
    content: var(--頂部文案-2);
    white-space: pre;
    font-family: var(--装饰字);
    text-align: center;
    position: absolute;
    top: 40px;
    left: calc(50% + 29.5%);
    transform: translateX(-50%);
    font-size: 1rem;
    line-height: 1.2;
    z-index: 5;
  }
}

:is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay):not(:empty) {
  padding: 0 0.3rem;
  background: var(--SmartThemeQuoteColor);
  border-left: none;
  border-right: none;
  margin-bottom: 1.75em;
  font-size: var(--ts-size);
}

#chat .mes .avatar {
  position: relative;
  flex: 0 0 auto;
  aspect-ratio: var(--头像比例);
  width: var(--头像大小);
  height: auto;
  margin: 0 5px 0 0;
  pointer-events: none;
  & img {
    border-radius: 0 !important;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center var(--User头像显示区域);
    border: none;
  }
}

#chat .mes[is_user="false"] .avatar img {
  object-position: center var(--Char头像显示区域);
}

#chat .mes .avatar {
  &::before {
    content: '';
    position: absolute;
    top: -25px;
    left: 52%;
    transform: translateX(-50%);
    aspect-ratio: 854 / 725;
    width: auto;
    height: calc(100% + 42px);
    background: url('https://files.catbox.moe/27nnwt.png') center / cover no-repeat;
  }
}

/* 名字 */
.mes .name_text {
  position: relative;
  overflow: visible;
  isolation: isolate;
  margin-left: 2.5rem;
  font-size: 1.75rem;
  line-height: 1;
  &::before {
    content: '“';
    position: absolute;
    left: -2em;
    font-size: 0.5em;
    border: 0.05em solid var(--SmartThemeQuoteColor);
    line-height: 0.5;
    padding-right: 0.25em;
  }
  &::after {
    content: var(--User名);
    z-index: -1;
    position: absolute;
    left: -1em;
    top: 0.18rem;
    color: var(--SmartThemeQuoteColor);
    font-size: 0.9em;
    font-family: var(--花体英文);
    white-space: nowrap;
  }
}

.mes[is_user="false"] .name_text::after {
  content: var(--Char名);
}

/* 时间戳 */
#chat .mes .timestamp {
  position: absolute;
  top: calc(-3px - var(--gap-1));
  right: 0;
  padding: 0 0.3rem;
  font-size: var(--ts-size);
  background: var(--SmartThemeQuoteColor);
  &::after {
    content: '';
    position: absolute;
    top: 5px;
    right: -0.3rem;
    aspect-ratio: 600 / 132;
    width: 200px;
    height: auto;
    opacity: 0.25;
    background: url('https://files.catbox.moe/c795lo.png') center / cover no-repeat;
  }
}

/* 小铅笔 */
.mes .ch_name {
  display: flex;
  align-items: flex-end;
}

.mes .mes_buttons { 
  align-self: flex-start;
}

.mes_button,
.mes_edit_buttons {
  filter: none !important;
  font-size: 0.95em;
}

.mes .menu_button {
  transform: scale(0.85);
  border-radius: 2px;
}

.mes_edit::before,
.extraMesButtonsHint::before {
  content: "\f00d";
}

/* 切换箭头 */
.last_mes {
  .swipe_right::before,
  .swipe_left::before {
    content: "▪";
    font-size: 0.75em;
  }
  .swipeRightBlock {
    left: 0;
    right: 0;
    padding-right: 20px;
    flex-direction: row-reverse;
  }
  .swipes-counter {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
  }
  .swipe_left {
    display: flex;
    transform: translateY(calc(var(--swipeCounterHeight, 0px) + var(--swipeCounterMargin, 0px)));
  }
  .swipe_left,
  .swipeRightBlock {
    margin-bottom: 0.3rem;
  }
}

/* 思维链 */
.mes_reasoning_header {
  margin: 0;
  background: transparent;
  & .mes_reasoning_arrow {
   display: none;
  }
}

.mes_reasoning_header_title {
  font-size: 0;
  &::before {
    content: var(--思维链文案);
    padding-left: 1em;
    font-size: 0.6rem;
    color: var(--SmartThemeEmColor);
  }
}

.mes_reasoning_details[open] .mes_reasoning_header_title::before {
  content: var(--思维链展开);
  color: red;
}

@media (max-width: 768px) {
  .mes_reasoning_details {
    position: relative;
}

  .mes_reasoning_details[open] {
    width: 100%;
}

  .mes_reasoning {
    width: 100%;
    margin-bottom: 0.5em;
    max-height: 500px;
    overflow: hidden auto;
    scrollbar-width: thin;
    font-size: 0.95em;
  }

  .mes_reasoning_actions {
     position: absolute;
     right: 0.3rem;
     flex-shrink: 0;
  }
}

/* 欢迎页 */
body .recentChat {
  border-radius: 2px !important;
  border: none !important;
  margin-bottom: 10px;
  backdrop-filter: blur(var(--气泡模糊)) !important;
  background: var(--SmartThemeChatTintColor);
  box-shadow:
    1px 1px 2px var(--shadow-1),
    0 0 3px var(--shadow-1);
}

.mes_button.showRecentChats .fa-circle-chevron-down::before {
  content: "◯";
}

.mes_button.hideRecentChats .fa-circle-xmark::before {
  content: "✖";
}

/*! ======= 底部输入框 ======== */
#send_form, 
body.no-blur #send_form {
  padding: 3px 8px;
  border-radius: 18px 18px 0 0;
  backdrop-filter: blur(var(--气泡模糊)) !important;
  background: var(--SmartThemeBlurTintColor) !important;
  border-width: 0.1px;
  outline: 0.5px solid var(--SmartThemeBorderColor);
  outline-offset: -3px;
  &:hover {
    outline: none !important;
  }
}

#nonQRFormItems {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  row-gap: 0;
}

#send_textarea {
  flex: 0 0 100%;
  order: -1;
  box-sizing: border-box;
  resize: none;
  border: none;
  clip-path: none;
  &:hover {
    clip-path: none;
  }
  /*&::placeholder {
    opacity: 0;
  }*/
}

/*#nonQRFormItems {
  --输入框文案: "发消息或按住说话";
  display: flex;
  position: relative;
  align-items: center;
  &::before {
    content: var(--输入框文案);
    display: none;
    position: absolute;
    left: 1rem;
    top: 25%;
    transform: translateY(-50%);
    font-size: calc(var(--mainFontSize) * 1);
    color: var(--SmartThemeEmColor);
    pointer-events: none;
    z-index: 1;
  }
}*/

#nonQRFormItems:has(#send_textarea:not(:focus):placeholder-shown)::before {
  display: block;
}


/* 图标 */
#leftSendForm > div {
  margin-right: 10px;
}

#options_button::before,
#extensionsMenuButton::before {
  content: "菜单";
  font-size: 0.4em;
  font-family: var(--装饰字) !important;
  padding: 2px 6px;
  border-radius: 8px;
  border: 0.8px solid var(--SmartThemeBorderColor);
}

#extensionsMenuButton::before {
  content: "扩展";
}

#send_form .fa-solid:not(#leftSendForm > div),
#quick-reply-rocket-button {
  font-size: 0.85em !important;
}

#send_but {
  background: var(--SmartThemeQuoteColor);
  -webkit-mask-image: url('https://i.postimg.cc/cHs143BW/wu-biao-ti228-20260308162848.png');
  mask-image: url('https://i.postimg.cc/cHs143BW/wu-biao-ti228-20260308162848.png');
  -webkit-mask-size: 75% auto;
  mask-size: 75% auto;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  &::before {
    content: '';
  }
}

/* qr */
#qr--bar {
  display: none !important;
}

#send_form:focus-within #qr--bar {
  display: flex !important;
}

#qr--bar > .qr--buttons .qr--button {
  border-radius: 5px !important;
  &:hover {
    background: none !important;
  }
  &:active {
    box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.2) !important;
  }
}

/* 魔棒&菜单 */
.list-group,
.options-content,
#options,
#quickPersonaImg {
  box-shadow: none !important;
}

.list-group-item .quickPersonaMenuImg {
  box-shadow: none;
  border: none;
}

/*! ======= 顶部菜单 ======= */
/* chattopbar */
#extensionTopBar {
  border: none !important;
  border-radius: 0 !important;
}

#top-bar, 
body.no-blur #top-bar {
  box-shadow: none;
}

/* 图标 */
#ai-config-button .drawer-icon,
#advanced-formatting-button .drawer-icon,
#user-settings-button .drawer-icon,
#extensions-settings-button .drawer-icon,
#persona-management-button .drawer-icon,
#sys-settings-button .drawer-icon,
#WI-SP-button .drawer-icon,
#logo_block .drawer-icon,
#backgrounds-drawer-toggle .drawer-icon,
#table_database_settings_drawer .drawer-icon,
#rightNavHolder .drawer-icon { 
  &::before {
    display: none;
  }
  overflow: visible;
  aspect-ratio: 1/1;
  width: var(--顶栏图标大小);
  background: var(--SmartThemeBorderColor);
  opacity: 1;
  -webkit-mask-size: contain;
  mask-size: contain;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  &:hover {
    background: var(--SmartThemeQuoteColor);
  }
}

#ai-config-button .drawer-icon {
  -webkit-mask-image: url('https://files.catbox.moe/iow9h6.png');
  mask-image: url('https://files.catbox.moe/iow9h6.png');
}

#sys-settings-button .drawer-icon {
  -webkit-mask-image: url('https://files.catbox.moe/5aa0b1.png');
  mask-image: url('https://files.catbox.moe/5aa0b1.png');
}

#sys-settings-button:has(.redOverlayGlow) .drawer-icon {
  background: red !important;
}

#advanced-formatting-button .drawer-icon {
  -webkit-mask-image: url('https://files.catbox.moe/22b5t1.png');
  mask-image: url('https://files.catbox.moe/22b5t1.png');
}

#WI-SP-button .drawer-icon {
  -webkit-mask-image: url('https://files.catbox.moe/174xi3.png');
  mask-image: url('https://files.catbox.moe/174xi3.png');
}

#user-settings-button .drawer-icon {
  -webkit-mask-image: url('https://files.catbox.moe/vobwib.png');
  mask-image: url('https://files.catbox.moe/vobwib.png');
}

#extensions-settings-button .drawer-icon {
  -webkit-mask-image: url('https://files.catbox.moe/d6nxmg.png');
  mask-image: url('https://files.catbox.moe/d6nxmg.png');
}

#persona-management-button .drawer-icon {
  -webkit-mask-image: url('https://files.catbox.moe/3hprhe.png');
  mask-image: url('https://files.catbox.moe/3hprhe.png');
}

#logo_block .drawer-icon,
#backgrounds-drawer-toggle .drawer-icon {
  -webkit-mask-image: url('https://files.catbox.moe/3kdj2e.png');
  mask-image: url('https://files.catbox.moe/3kdj2e.png');
}

#rightNavHolder .drawer-icon{ 
  -webkit-mask-image: url('https://files.catbox.moe/k3zudj.png');
  mask-image: url('https://files.catbox.moe/k3zudj.png');
}

/*! ======= 抽屉页 ======= */
body .drawer-content,
#left-nav-panel,
#right-nav-panel {
  border-radius: 0 0 5px 5px;
  border: none;
  top: var(--bottomFormBlockSize);
}

@media (max-width: 768px) {
  #left-nav-panel,
  #right-nav-panel {
    top: var(--bottomFormBlockSize) !important;
  }
}

.standoutHeader,
.inline-drawer-header,
#user-settings-block h4,
#rm_extensions_block .inline-drawer-toggle.inline-drawer-header {
  padding: 3px 5px;
  margin-bottom: 3px;
  background: var(--color-1);
  border: none;
  outline: 0.5px solid var(--SmartThemeBorderColor);
  outline-offset: -2px;
  border-radius: 2px;
  box-shadow: 1px 1px 4px var(--shadow-1);
  &:hover {
    filter: none;
  }
}

.inline-drawer-icon {
  color: var(--SmartThemeBorderColor);
  opacity: 0.75;
  font-size: 1em;
  padding: 2px;
}

.inline-drawer-icon::before {
  content: "\f103";
}

.inline-drawer-icon.up::before {
  content: "\f102";
}

/* 下拉框 */
#character_sort_order,
select.text_pole,
select:not(#extensionTopBarChatName) {
  background-color: var(--black30a);
  border: 0.2px solid var(--SmartThemeBorderColor);
  border-right: none;
  border-left: none;
  border-radius: 0px;
  box-shadow:
    0 1px 0 0.5px var(--black30a),
    0 -1px 0 0.5px var(--black30a),
    1px 1px 2px var(--shadow-1);
}

#tag_import_setting {
  margin-top: 5px;
}

/* 输入框 */
input:not([type]),
input[type="text"],
input[type="search"],
input[type="number"],
textarea.text_pole,
textarea.textarea_compact,
textarea:not(#send_textarea) {
  outline: none;
  border-radius: 2px;
  box-shadow: 1px 1px 2px var(--shadow-1);
  &:hover {
    outline: none !important;
    border-style: double !important;
  }
}

#user-settings-block input[type="number"] {
  border-radius: 0;
  border: none;
}

/* 滑动条 */
input[type="range"] {
  background: 
    linear-gradient(185deg, var(--SmartThemeBorderColor) 0%, var(--SmartThemeBlurTintColor) 100%) !important;
  border-radius: 0 !important;
  height: 2px !important;
  filter: none !important;
}

input[type="range"]::-webkit-slider-thumb {
  filter: none !important;
  background:
    linear-gradient(135deg, var(--SmartThemeBorderColor) 0%, var(--SmartThemeBlurTintColor) 100%);
  border-radius: 0;
  border: none;
  transform: scale(0.55) rotate(45deg);
  box-shadow: 
    1px 1px 1px rgba(0, 0, 0, 0.2),
    -1px -1px 1px rgba(197, 197, 197, 0.1);
}

/* 按钮 */
.menu_button {
  border-radius: 0;
  background: var(--color-1);
  outline: 0.5px solid var(--SmartThemeBorderColor);
  outline-offset: -2px;
  border-width: 0.5px;
  box-shadow: 1px 1px 1px var(--shadow-1);
  filter: none;
}

#bulkDeleteButton,
#delete_button,
#persona_delete_button,
#world_popup_delete,
.menu_button.popup-button-ok,
#delete_connection_profile,
#delete_oai_preset,
#dialogue_del_mes_ok,
.mes_edit_cancel.menu_button,
.mes_edit_buttons .mes_edit_delete {
  background: #B13C3C !important;
  color: #222 !important;
}

/* 勾选 */
input[type="checkbox"] {
  background: color-mix(in srgb, var(--SmartThemeBorderColor) 50%, transparent);
  border-radius: 2px;
  filter: none;
  border: none;
  outline: none;
}

.checkbox_label {
  display: flex;
  align-items: center;
}

input[type="checkbox"]:checked {
  background: transparent !important;
  box-shadow: inset 0 0 4px var(--SmartThemeQuoteColor) !important;
  transform: scale(0.85) translate(-2.8px, -3px) rotate(-15deg);
  border-radius: 50%;
  box-shadow: 2px 3px 0 1px var(--SmartThemeQuoteColor) !important;
}

input[type="checkbox"]::before {
  content: none;
}

/* 弹窗 */
#select_chat_popup,
.popup:not(.transparent_dialogue_popup) {
  border-radius: 2px;
  background: var(--color-1);
  outline: 0.5px solid var(--SmartThemeBorderColor);
  outline-offset: -2px;
  box-shadow: 1px 1px 5px var(--shadow-1);
}

.popup-content:has(#showRawPrompt) {
  overflow-y: auto;
}

.toast {
  border-radius: 1px !important;
  outline: 1px solid var(--SmartThemeBorderColor);
  outline-offset: -3px;
  box-shadow: 1px 1px 5px var(--shadow-1) !important;
}

.toast-success {
  background-color: var(--SmartThemeQuoteColor) !important;
}

.toast-error {
  background-color: #FE575F !important;
}

.toast-info {
  background-color: #348EFE !important;
}

.toast-warning {
  background-color: #FEB834 !important;
