/* 正则 */
@media (hover: none) and (pointer: coarse) {
  .regex-script-label {
    pointer-events: none;
  }

  .regex-script-label > *:not(.regex_script_name) {
    pointer-events: auto;
  }

  .regex-script-label .drag-handle {
    pointer-events: auto;
    padding: 6px 10px;
  }
}

.regex-script-label {
  border-radius: 1px !important;
  border: none;
}

.regex_script_name {
  white-space: normal;
}

.regex-script-label.flex-container {
  align-items: center;
}

.regex-toggle-on {
  color: var(--SmartThemeBorderColor);
}

.regex-script-label:has(.disable_regex:not(:checked)) {
  background-color: var(--color-1) !important;
}

/* 世界书 */
.world_entry {
  margin-top: 20px;
}

.wi-card-entry {
  border: none;
  border-radius: 5px;
}

#wiTopBlock .inline-drawer.wide100p .inline-drawer-content {
  border-radius: 5px;
  margin-top: 5px;
}

@media screen and (max-width: 768px) {
  /* 定义响应式下的变量（可根据需要调整） */
  :root {
    --btn-size: 1.5rem; /* 按钮宽高 */
    --btn-gap: 0.25rem; /* 按钮间隙 */
    --btn-offset-bottom: 5px; /* 按钮距离底部的距离 */
    --btn-offset-start: 5px;  /* 最右侧按钮距离右边的距离  */
  }

  /* 字体大小 */
  .world_entry_form .text_pole {
    font-size: 0.8rem;
  }

  /* 条目头部设为相对定位容器 */
  .world_entry_form .inline-drawer-header {
    position: relative;
  }

  .world_entry_form .inline-drawer-header > .menu_button {
    position: absolute;
    bottom: var(--btn-offset-bottom);
    margin: 0;
    width: var(--btn-size);
    height: var(--btn-size);
  }

  /* 各个按钮的具体位置（基于变量计算） */
  .world_entry_form .inline-drawer-header > .move_entry_button {
    right: var(--btn-offset-start);
  }

  .world_entry_form .inline-drawer-header > .duplicate_entry_button {
    right: calc(var(--btn-offset-start) + var(--btn-size) + var(--btn-gap));
  }

  .world_entry_form .inline-drawer-header > .delete_entry_button {
    right: calc(var(--btn-offset-start) + (var(--btn-size) + var(--btn-gap)) * 2);
  }
}




